import hmac
import json
import re

from payhook.errors import InvalidNotification

_CURRENCY_RE = re.compile(r"[A-Z]{3}")
_WINDOW = 300


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    raw_stamp = headers.get("X-Pay-Timestamp")
    if not isinstance(raw_stamp, str):
        raise InvalidNotification("missing timestamp")
    try:
        stamp = int(raw_stamp)
    except (ValueError, TypeError):
        raise InvalidNotification("malformed timestamp")
    if abs(stamp - now) > _WINDOW:
        raise InvalidNotification("stale delivery")

    try:
        data = json.loads(raw_body)
    except Exception:
        raise InvalidNotification("malformed body")
    if not isinstance(data, dict):
        raise InvalidNotification("body not an object")

    event_id = data.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("missing event_id")

    account_id = data.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("missing account_id")

    amount_minor = data.get("amount_minor")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("missing amount_minor")
    if amount_minor < 0:
        raise InvalidNotification("negative amount_minor")

    currency = data.get("currency")
    if not isinstance(currency, str) or not _CURRENCY_RE.fullmatch(currency):
        raise InvalidNotification("missing currency")

    stamp_bytes = raw_stamp.encode("ascii")
    result = {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }

    v1_header = headers.get("X-Pay-Signature", "")
    if isinstance(v1_header, str) and v1_header.startswith("v1="):
        expected = hmac.new(
            secret, stamp_bytes + b"." + raw_body, hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(v1_header[3:], expected):
            return result

    r0_header = headers.get("X-Pay-Receipt", "")
    if isinstance(r0_header, str) and r0_header.startswith("r0="):
        expected = hmac.new(
            secret, stamp_bytes + b"." + event_id.encode("utf-8"), hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(r0_header[3:], expected):
            return result

    raise InvalidNotification("invalid signature")"}

